function loadState(){ const saved=localStorage.getItem(STORAGE_KEY); if(!saved) return seedState(); try{ const parsed=JSON.parse(saved); ['users','orders','submissions','responses','chats','marketplace_items','payment_requests','withdraw_requests','notifications'].forEach(k=>{if(!Array.isArray(parsed[k])) parsed[k]=[];}); const session=getSession(); if(session&&parsed.users.some(u=>String(u.tg_id)===String(session.tg_id))) parsed.current_tg_id=session.tg_id; if(!parsed.current_tg_id&&parsed.users[0]) parsed.current_tg_id=parsed.users[0].tg_id; return parsed; }catch{return seedState();} }
function saveState(){ localStorage.setItem(STORAGE_KEY,JSON.stringify(state)); }
function getSession(){ try{return JSON.parse(localStorage.getItem(AUTH_KEY)||'null');}catch{return null;} }
function setSession(user){ localStorage.setItem(AUTH_KEY,JSON.stringify({tg_id:user.tg_id,username:user.username,login_at:new Date().toISOString()})); }
function makeUser(d){return {tg_id:d.tg_id,username:d.username,name:d.name||d.username,email:d.email||'',phone:d.phone||'',skills:d.skills||[],role:d.role||'freelancer',balance_usd:Number(d.balance_usd||0),balance_uzs:Number(d.balance_uzs||0),balance_freecoins:Number(d.balance_freecoins||0),rating:Number(d.rating||5),created_at:d.created_at||new Date().toISOString()};}
function makeOrder(d){return {id:d.id||fallbackId(),client_id:d.client_id,title:d.title,description:d.description,category:d.category,currency:d.currency,budget:Number(d.budget),status:d.status||'open',created_at:d.created_at||new Date().toISOString(),expires_at:d.expires_at||iso(Date.now()+1000*60*60*72)};}
function makeSubmission(d){return {id:d.id||fallbackId(),order_id:d.order_id,freelancer_id:d.freelancer_id,result_link:d.result_link,comment:d.comment||'',status:d.status||'pending',created_at:d.created_at||new Date().toISOString()};}
function makeResponse(d){return {id:d.id||fallbackId(),order_id:d.order_id,freelancer_id:d.freelancer_id,message:d.message||'',proposed_budget:Number(d.proposed_budget||0),eta_days:Number(d.eta_days||0),status:d.status||'new',created_at:d.created_at||new Date().toISOString()};}
function makeChat(d){return {id:d.id||fallbackId(),order_id:d.order_id,client_id:d.client_id,freelancer_id:d.freelancer_id,messages:d.messages||[],status:d.status||'active',created_at:d.created_at||new Date().toISOString()};}
function makeMessage(d){return {id:d.id,sender_id:d.sender_id,text:d.text,created_at:d.created_at||new Date().toISOString()};}
function makeMarketItem(d){return {id:d.id||fallbackId(),author_id:d.author_id,title:d.title,description:d.description,result_link:d.result_link,category:d.category,currency:d.currency,price:Number(d.price),sales_count:Number(d.sales_count||0),created_at:d.created_at||new Date().toISOString()};}
function render(){ document.documentElement.lang=lang; if(!getSession()){renderAuthScreen();return;} const user=currentUser(); if(!user){renderAuthScreen();return;} app.innerHTML=`<header class="app-header"><div class="header-row"><div class="brand"><div class="brand-mark">FD</div><div><div class="brand-title">FreeDom</div><div class="brand-subtitle">${t('subtitle')}</div></div></div><button class="wallet-pill" data-action="open-profile"><span>${user.role==='client'?t('paymentMode'):t('balance')}</span><strong>${user.role==='client'?t('payByResultShort'):formatMainBalance(user)}</strong><span>${user.role==='client'?t('payAfterApproval'):`${formatNumber(user.balance_freecoins)} FC`}</span></button></div><div class="role-toggle"><button class="${user.role==='freelancer'?'active':''}" data-role="freelancer">${t('freelancer')}</button><button class="${user.role==='client'?'active':''}" data-role="client">${t('client')}</button></div><div class="quick-actions"><button class="icon-action" data-action="go-back" title="${t('back')}" aria-label="${t('back')}">←</button><button class="quick-pill" data-action="open-tools">${t('toolsMenu')}</button><button class="icon-action" data-action="open-site" title="${t('site')}" aria-label="${t('site')}">↗</button><div class="app-lang-switch compact-lang">${SUPPORTED.map(code=>`<button class="${lang===code?'active':''}" data-action="set-lang" data-lang="${code}">${code.toUpperCase()}</button>`).join('')}</div></div>${user.role==='client'&&view.tab==='exchange'?`<button class="hero-action" data-action="create-order">${t('createOrder')}</button>`:''}</header>${view.tab==='exchange'?renderExchange(user):''}${view.tab==='market'?renderMarket():''}${view.tab==='chats'?renderChats(user):''}${view.tab==='profile'?renderProfile(user):''}<nav class="tabbar">${tabButton('exchange',t('exchange'),'FD')}${tabButton('market',t('market'),'M')}${tabButton('chats',t('chats'),'C')}${tabButton('profile',t('profile'),'P')}</nav>`; bindPageEvents(); }
function renderAuthScreen(){ app.innerHTML=`<section class="auth-screen"><div class="auth-panel"><div class="brand auth-brand"><div class="brand-mark">FD</div><div><div class="brand-title">FreeDom</div><div class="brand-subtitle">EN / RU / UZ</div></div></div><div class="app-lang-switch auth-lang">${SUPPORTED.map(code=>`<button class="${lang===code?'active':''}" data-auth-lang="${code}">${code.toUpperCase()}</button>`).join('')}</div><h1>${t('registerTitle')}</h1><p>${t('registerText')}</p><div class="auth-manifest"><strong>FreeDom:</strong> ${t('manifest')}</div></div><form class="auth-form" id="registerForm"><div class="field"><label>${t('name')}</label><input class="input" name="name" required placeholder="Aziz Backend"></div><div class="field"><label>${t('email')}</label><input class="input" name="email" type="email" required placeholder="you@example.com"></div><div class="field"><label>${t('phone')}</label><input class="input" name="phone" required placeholder="@username or +998..."></div><div class="field"><label>${t('role')}</label><div class="auth-choice"><label><input type="radio" name="role" value="freelancer" checked> ${t('freelancer')}</label><label><input type="radio" name="role" value="client"> ${t('client')}</label></div></div><div class="field"><label>${t('skills')}</label><div class="skill-picker">${['bots','sites','automation','chatbots'].map(id=>`<label><input type="checkbox" name="skills" value="${id}"> ${categoryLabel(id)}</label>`).join('')}</div></div><div class="terms-line" style="display:flex;align-items:flex-start;gap:12px;"><input type="checkbox" name="terms" required style="margin-top:4px;"><span style="font-size:0.875rem;">${t('terms')}</span></div><button class="primary-btn full">${t('register')}</button></form></section>`; document.querySelectorAll('[data-auth-lang]').forEach(b=>b.addEventListener('click',()=>setLanguage(b.dataset.authLang))); document.getElementById('registerForm').addEventListener('submit',e=>{e.preventDefault(); const form=new FormData(e.currentTarget); const email=String(form.get('email')).trim(); const phone=String(form.get('phone')).trim(); const existing=state.users.find(u=>u.email===email||u.phone===phone); if(existing){state.current_tg_id=existing.tg_id;setSession(existing);saveState();render();toast(t('existing'));return;} const name=String(form.get('name')).trim(); const user=makeUser({tg_id:Date.now(),name,username:makeUsername(name),email,phone,role:form.get('role'),skills:form.getAll('skills'),rating:5}); state.users.push(user); state.current_tg_id=user.tg_id; setSession(user); saveState(); render(); toast(t('welcome'));}); }function renderExchange(user){return user.role==='client'?renderClientExchange(user):renderFreelancerExchange(user);}
function renderFreelancerExchange(user){const orders=filteredOrders();return `<section class="work-surface">${renderHero(user,orders)}<div class="section-title"><div><h1>${t('orderExchange')}</h1><p>${t('freelancerHint')}</p></div><span class="count-badge">${orders.length} ${t('open')}</span></div>${renderOrderFilters()}<div class="feed">${orders.map(renderOrderCard).join('')||`<div class="empty">${t('noOrders')}</div>`}</div></section>`;}
function renderClientExchange(user){const orders=state.orders.filter(o=>o.client_id===user.tg_id).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));return `<section class="work-surface">${renderHero(user,orders)}<div class="section-title"><div><h1>${t('clientOrders')}</h1><p>${t('clientHint')}</p></div><span class="count-badge">${orders.length} ${t('total')}</span></div><div class="feed">${orders.map(renderClientOrderCard).join('')||`<div class="empty">${t('noClientOrders')}</div>`}</div></section>`;}
function renderHero(user,orders){const top=orders[0];return `<div class="workspace-hero"><div><span class="hero-label">${user.role==='client'?t('clientWorkspace'):t('workspace')}</span><h2>${top?escapeHtml(localized(top.title)):(user.role==='client'?t('clientHint'):t('freelancerHint'))}</h2><p>${top?escapeHtml(localized(top.description)):(user.role==='client'?t('clientHint'):t('freelancerHint'))}</p></div><div class="hero-metrics"><div><span>${t('balance')}</span><strong>${formatMoney(user.balance_usd,'USD')}</strong></div><div><span>FreeCoins</span><strong>${formatNumber(user.balance_freecoins)} FC</strong></div><div><span>${t('available')}</span><strong>${orders.length}</strong></div></div></div>`;}
function renderOrderFilters(){return `<div class="toolbar"><select class="select" id="orderCurrency">${['all','USD','UZS'].map(x=>`<option value="${x}" ${view.orderCurrency===x?'selected':''}>${x==='all'?t('all'):x}</option>`).join('')}</select><input class="input" id="orderSearch" value="${escapeAttr(view.orderSearch)}" placeholder="${t('searchOrders')}"></div><div class="chip-row">${categoryIds.map(id=>`<button class="chip ${view.orderCategory===id?'active':''}" data-category="${id}">${categoryLabel(id)}</button>`).join('')}</div>`;}
function renderOrderCard(order){const responses=responsesFor(order.id);const submissions=submissionsFor(order.id);return `<article class="card order-card"><div class="card-top"><h3>${escapeHtml(localized(order.title))}</h3><div class="price">${formatMoney(order.budget,order.currency)}</div></div><p class="desc">${escapeHtml(localized(order.description))}</p><div class="meta-row"><span class="meta status-open">${t('resultBased')}</span><span class="meta">${t('left')}: ${timeLeft(order.expires_at)}</span><span class="meta">${t('responses')}: ${responses.length}</span><span class="meta">${t('results')}: ${submissions.length}</span><span class="meta">${categoryLabel(order.category)}</span></div><button class="primary-btn full" data-action="open-order" data-id="${order.id}">${t('openTask')}</button></article>`;}
function renderClientOrderCard(order){const responses=responsesFor(order.id);const submissions=submissionsFor(order.id);return `<article class="card client-card"><div class="card-top"><h3>${escapeHtml(localized(order.title))}</h3><div class="price">${formatMoney(order.budget,order.currency)}</div></div><p class="desc">${escapeHtml(localized(order.description))}</p><div class="meta-row"><span class="meta ${statusClass(order.status)}">${statusLabel(order.status)}</span><span class="meta">${t('responses')}: ${responses.length}</span><span class="meta">${t('results')}: ${submissions.length}</span><span class="meta">${categoryLabel(order.category)}</span></div><button class="secondary-btn full" data-action="review-order" data-id="${order.id}">${t('review')}</button></article>`;}
function renderMarket(){const items=filteredMarket();return `<section><div class="section-title"><div><h1>${t('marketplace')}</h1><p>${t('marketplaceHint')}</p></div><span class="count-badge">${items.length} ${t('items')}</span></div><div class="toolbar"><input class="input" id="shopMin" value="${escapeAttr(view.shopMin)}" inputmode="numeric" placeholder="Min"><input class="input" id="shopMax" value="${escapeAttr(view.shopMax)}" inputmode="numeric" placeholder="Max"></div><input class="input" id="shopSearch" value="${escapeAttr(view.shopSearch)}" placeholder="${t('searchMarket')}"><div class="market-grid" style="margin-top:12px;">${items.map(renderMarketCard).join('')||`<div class="empty">${t('noMarket')}</div>`}</div></section>`;}
function renderMarketCard(item){const author=userById(item.author_id);return `<article class="card market-card"><div class="market-cover">${categoryLabel(item.category)}</div><div class="market-body"><h3>${escapeHtml(localized(item.title))}</h3><div class="price">${formatMoney(item.price,item.currency)}</div><small>${t('author')}: @${escapeHtml(author?.username||'freelancer')}</small><small>${t('sales')}: ${item.sales_count}</small><div class="market-actions"><button class="secondary-btn" data-action="open-preview" data-link="${escapeAttr(item.result_link)}">${t('openLink')}</button><button class="primary-btn" data-action="buy-item" data-id="${item.id}">${t('buyCopy')}</button></div></div></article>`;}
function renderChats(user){const chats=chatsForUser(user.tg_id).sort((a,b)=>new Date(lastChatMessage(b)?.created_at||b.created_at)-new Date(lastChatMessage(a)?.created_at||a.created_at));return `<section class="stack"><div class="section-title"><div><h1>${t('chatTitle')}</h1><p>${t('chatHint')}</p></div><span class="count-badge">${chats.length} ${t('active')}</span></div><div class="chat-list">${chats.map(renderChatCard).join('')||`<div class="empty">${t('noChats')}</div>`}</div></section>`;}
function renderChatCard(chat){const user=currentUser();const order=orderById(chat.order_id);const other=user.tg_id===chat.client_id?userById(chat.freelancer_id):userById(chat.client_id);const last=lastChatMessage(chat);return `<article class="chat-card"><div class="chat-card-main"><div class="avatar">${initials(other?.username||'FD')}</div><div><strong>@${escapeHtml(other?.username||'user')}</strong><span>${escapeHtml(localized(order?.title)||'Order')}</span><p>${escapeHtml(localized(last?.text)||t('chatOpen'))}</p></div></div><button class="secondary-btn" data-action="open-chat" data-id="${chat.id}">${t('openChat')}</button></article>`;}
function renderProfile(user){const isClient=user.role==='client';const notifications=state.notifications.filter(n=>n.user_id===user.tg_id).slice(-4).reverse();const payments=[...state.payment_requests.filter(x=>x.user_id===user.tg_id),...state.withdraw_requests.filter(x=>x.user_id===user.tg_id).map(x=>({...x,type:'withdraw'}))].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).slice(0,5);const walletCards=isClient?`<div class="wallet-card payment-mode-card"><div><span>${t('payByDeal')}</span><strong>${t('noPreload')}</strong><small>${t('checkoutOrderNote')}</small></div></div><div class="wallet-card payment-mode-card"><div><span>${t('serviceFee')}</span><strong>${Math.round(FEE*100)}%</strong><small>${t('payAfterApproval')}</small></div></div><div class="wallet-card"><div><span>FreeCoins</span><strong>${formatNumber(user.balance_freecoins)} FC</strong></div><div class="wallet-actions"><button class="ghost-btn" data-action="spend-fc">FC</button><button class="danger-btn" data-action="logout">${t('logout')}</button></div></div>`:`<div class="wallet-card"><div><span>USD</span><strong>${formatMoney(user.balance_usd,'USD')}</strong><small>${t('availableToWithdraw')}</small></div><div class="wallet-actions"><button class="ghost-btn" data-action="withdraw" data-currency="USD">${t('withdraw')}</button></div></div><div class="wallet-card"><div><span>UZS</span><strong>${formatMoney(user.balance_uzs,'UZS')}</strong><small>${t('availableToWithdraw')}</small></div><div class="wallet-actions"><button class="ghost-btn" data-action="withdraw" data-currency="UZS">${t('withdraw')}</button></div></div><div class="wallet-card"><div><span>FreeCoins</span><strong>${formatNumber(user.balance_freecoins)} FC</strong></div><div class="wallet-actions"><button class="ghost-btn" data-action="spend-fc">FC</button><button class="danger-btn" data-action="logout">${t('logout')}</button></div></div>`;return `<section class="stack"><div class="card profile-card"><div class="profile-main"><div class="avatar">${initials(user.username)}</div><div><h1 style="margin:0;">@${escapeHtml(user.username)}</h1><p style="margin:5px 0;color:var(--muted);">${isClient?t('client'):t('freelancer')} · ${stars(user.rating)} ${user.rating.toFixed(1)}</p></div></div></div><div class="section-title"><h2>${isClient?t('paymentMode'):t('wallet')}</h2></div><div class="wallet-grid">${walletCards}</div><div class="section-title"><h2>${isClient?t('clientPayments'):t('freelancerPayouts')}</h2></div><div class="stack">${payments.map(renderPaymentItem).join('')||`<div class="empty">${t('noPayments')}</div>`}</div><div class="section-title"><h2>${t('perks')}</h2></div>${renderPerk(t('perkColor'),500)}${renderPerk(t('perkTop'),1000)}${renderPerk(t('perkVip'),1500)}<div class="section-title"><h2>${t('notifications')}</h2></div><div class="stack">${notifications.map(n=>`<div class="notice">${escapeHtml(localized(n.text))}</div>`).join('')||`<div class="empty">${t('noNotifications')}</div>`}</div></section>`;}function renderPaymentItem(item){const labels={withdraw:t('withdraw'),order_payment:t('orderPayment'),marketplace_purchase:t('marketPurchase'),marketplace_sale:t('marketplaceSale'),payout:t('freelancePayout'),topup:t('orderPayment')};const positive=['marketplace_sale','payout'].includes(item.type);const negative=['withdraw','order_payment','marketplace_purchase'].includes(item.type);return `<div class="payment-row"><div><strong>${labels[item.type]||item.type||t('payments')}</strong><span>${escapeHtml(item.title||item.method||item.destination||'')}</span></div><div class="payment-right"><strong>${positive?'+':negative?'-':''}${formatMoney(item.amount,item.currency)}</strong><em>${item.status==='paid'?t('paid'):t('pending')}</em></div></div>`;}function renderPerk(title,price){return `<div class="perk"><div class="perk-top"><strong>${title}</strong><span class="price">${formatNumber(price)} FC</span></div><button class="ghost-btn full" data-action="buy-perk" data-price="${price}" data-title="${escapeAttr(title)}">${t('activate')}</button></div>`;}
function bindPageEvents(){document.querySelectorAll('[data-role]').forEach(b=>b.addEventListener('click',()=>{updateCurrentUser({role:b.dataset.role});render();}));document.querySelectorAll('.tabbar button').forEach(b=>b.addEventListener('click',()=>setTab(b.dataset.tab)));document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{view.orderCategory=b.dataset.category;render();}));bindInput('orderSearch',v=>view.orderSearch=v);bindInput('orderCurrency',v=>view.orderCurrency=v);bindInput('shopSearch',v=>view.shopSearch=v);bindInput('shopMin',v=>view.shopMin=v);bindInput('shopMax',v=>view.shopMax=v);document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>handleAction(b.dataset)));}
function bindInput(id,onChange){const input=document.getElementById(id);if(!input)return;const ev=input.tagName==='SELECT'?'change':'input';input.addEventListener(ev,()=>{onChange(input.value);if(ev==='change')return render();clearTimeout(delayedRender);delayedRender=setTimeout(render,220);});}
function handleAction(data){const id=Number(data.id);const actions={'open-profile':()=>setTab('profile'),'set-tab':()=>setTab(data.target),'set-lang':()=>setLanguage(data.lang),'go-back':goBack,'open-tools':openToolsMenu,'open-ai':openAIAssistant,'open-generator':openGenerator,'open-justice':openJusticeReport,'open-site':()=>window.location.href='index.html','create-order':openCreateOrder,'open-order':()=>openOrderSheet(id),'review-order':()=>openReviewSheet(id),'open-chat':()=>openChatSheet(id),'contact-response':()=>contactResponse(id),'contact-submission':()=>contactSubmission(id),'open-preview':()=>window.open(data.link,'_blank','noopener,noreferrer'),'buy-item':()=>buyMarketplaceItem(id),withdraw:()=>openWithdraw(data.currency),logout:logoutUser,'spend-fc':()=>toast(t('perks')),'buy-perk':()=>buyPerk(Number(data.price),data.title)};actions[data.action]?.();}
function setTab(tab,remember=true){if(!tab||tab===view.tab)return;if(remember)viewHistory.push(view.tab);view.tab=tab;render();}
function goBack(){if(sheetLayer.classList.contains('active'))return closeSheet();const prev=viewHistory.pop();if(prev){view.tab=prev;render();}}function openOrderSheet(orderId){const order=orderById(orderId);if(!order)return;openSheet(`<div class="sheet-head"><h2>${escapeHtml(localized(order.title))}</h2><button class="close-btn" data-close>×</button></div><div class="sheet-body"><div class="meta-row"><span class="meta status-open">${formatMoney(order.budget,order.currency)}</span><span class="meta">${categoryLabel(order.category)}</span><span class="meta">${t('left')}: ${timeLeft(order.expires_at)}</span></div><p style="line-height:1.55;">${escapeHtml(localized(order.description))}</p><div class="notice">${t('taskNote')}</div><form class="form-grid" id="responseForm" style="margin-top:12px;"><div class="field"><label>${t('responseForClient')}</label><textarea class="textarea" name="message" required placeholder="${t('responsePlaceholder')}"></textarea></div><div class="inline-fields"><div class="field"><label>${t('yourPrice')}</label><input class="input" name="price" inputmode="decimal"></div><div class="field"><label>${t('eta')}</label><input class="input" name="days" inputmode="numeric"></div></div><button class="secondary-btn full">${t('respondChat')}</button></form><form class="form-grid" id="submissionForm" style="margin-top:14px;"><div class="field"><label>${t('resultLink')}</label><input class="input" name="result" type="url" required placeholder="https://..."></div><div class="field"><label>${t('commentClient')}</label><textarea class="textarea" name="comment"></textarea></div><button class="primary-btn full">${t('sendResult')}</button></form></div>`);document.getElementById('responseForm').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);sendResponse(order,{message:f.get('message'),proposed_budget:Number(String(f.get('price')||0).replace(',','.')),eta_days:Number(String(f.get('days')||0).replace(',','.'))});});document.getElementById('submissionForm').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);submitResult(order,f.get('result'),f.get('comment'));});}
function openCreateOrder(){let selectedCurrency='USD';openSheet(`<div class="sheet-head"><h2>${t('createOrder')}</h2><button class="close-btn" data-close>×</button></div><div class="sheet-body"><form class="form-grid" id="orderForm"><div class="field"><label>${t('title')}</label><input class="input" name="title" required></div><div class="field"><label>${t('description')}</label><textarea class="textarea" name="description" required></textarea></div><div class="field"><label>${t('category')}</label><select class="select" name="category">${categoryIds.filter(id=>id!=='all').map(id=>`<option value="${id}">${categoryLabel(id)}</option>`).join('')}</select></div><div class="field"><label>${t('currency')}</label><div class="currency-toggle"><button type="button" class="active" data-currency-pick="USD">USD</button><button type="button" data-currency-pick="UZS">UZS</button></div></div><div class="field"><label>${t('budget')}</label><input class="input" name="budget" inputmode="decimal" required></div><button class="primary-btn full">${t('publish')}</button></form></div>`);document.querySelectorAll('[data-currency-pick]').forEach(b=>b.addEventListener('click',()=>{selectedCurrency=b.dataset.currencyPick;document.querySelectorAll('[data-currency-pick]').forEach(x=>x.classList.toggle('active',x===b));}));document.getElementById('orderForm').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);createOrder({title:{en:f.get('title'),ru:f.get('title'),uz:f.get('title')},description:{en:f.get('description'),ru:f.get('description'),uz:f.get('description')},category:f.get('category'),currency:selectedCurrency,budget:Number(String(f.get('budget')).replace(',','.'))});});}
function openReviewSheet(orderId){const order=orderById(orderId);if(!order)return;const responses=responsesFor(orderId);const submissions=submissionsFor(orderId);openSheet(`<div class="sheet-head"><h2>${escapeHtml(localized(order.title))}</h2><button class="close-btn" data-close>×</button></div><div class="sheet-body"><div class="notice">${t('reviewNote')}</div><div class="review-grid"><section><h3>${t('responsesContact')}</h3><div class="stack">${responses.map(r=>renderResponseBlock(r,order)).join('')||`<div class="empty">${t('noResponses')}</div>`}</div></section><section><h3>${t('readyResults')}</h3><div class="stack">${submissions.map(s=>renderSubmissionBlock(s,order)).join('')||`<div class="empty">${t('noResults')}</div>`}</div></section></div></div>`);document.querySelectorAll('[data-winner]').forEach(b=>b.addEventListener('click',()=>completeOrder(orderId,Number(b.dataset.winner))));document.querySelectorAll('[data-test-link]').forEach(b=>b.addEventListener('click',()=>window.open(b.dataset.testLink,'_blank','noopener,noreferrer')));}
function renderResponseBlock(r,order){const u=userById(r.freelancer_id);const price=r.proposed_budget?formatMoney(r.proposed_budget,order.currency):formatMoney(order.budget,order.currency);return `<div class="response-card"><div class="submission-head"><div class="person"><div class="avatar">${initials(u?.username||'FD')}</div><div><strong>@${escapeHtml(u?.username||'freelancer')}</strong><small>${stars(u?.rating||4.8)} ${(u?.rating||4.8).toFixed(1)}</small></div></div><span class="meta status-open">${t('responses')}</span></div><p class="desc" style="-webkit-line-clamp:unset;">${escapeHtml(localized(r.message))}</p><div class="meta-row"><span class="meta">${t('yourPrice')}: ${price}</span><span class="meta">${t('eta')}: ${r.eta_days||'-'}</span></div><button class="secondary-btn full" data-action="contact-response" data-id="${r.id}">${t('contact')}</button></div>`;}
function renderSubmissionBlock(s,order){const u=userById(s.freelancer_id);return `<div class="submission"><div class="submission-head"><div class="person"><div class="avatar">${initials(u?.username||'FD')}</div><div><strong>@${escapeHtml(u?.username||'freelancer')}</strong><small>${stars(u?.rating||4.8)} ${(u?.rating||4.8).toFixed(1)}</small></div></div><span class="meta ${statusClass(s.status)}">${submissionLabel(s.status)}</span></div><p class="desc" style="-webkit-line-clamp:unset;">${escapeHtml(localized(s.comment))}</p><div class="split-actions three-actions"><button class="ghost-btn" data-action="contact-submission" data-id="${s.id}">${t('contact')}</button><button class="secondary-btn" data-test-link="${escapeAttr(s.result_link)}">${t('test')}</button><button class="primary-btn" data-winner="${s.id}" ${order.status==='completed'?'disabled':''}>${t('payWinner')}</button></div></div>`;}
function openSheet(html){sheetLayer.innerHTML=`<div class="sheet">${html}</div>`;sheetLayer.classList.add('active');sheetLayer.setAttribute('aria-hidden','false');sheetLayer.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',closeSheet));sheetLayer.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>handleAction(b.dataset)));sheetLayer.addEventListener('click',closeOnLayerClick);}
function closeOnLayerClick(e){if(e.target===sheetLayer)closeSheet();}
function closeSheet(){sheetLayer.classList.remove('active');sheetLayer.setAttribute('aria-hidden','true');sheetLayer.removeEventListener('click',closeOnLayerClick);sheetLayer.innerHTML='';}
function sendResponse(order,data){const user=currentUser();const message=String(data.message||'').trim();if(!message)return;let response=state.responses.find(x=>x.order_id===order.id&&x.freelancer_id===user.tg_id);const msg={en:message,ru:message,uz:message};if(response)Object.assign(response,{message:msg,proposed_budget:Number(data.proposed_budget||0),eta_days:Number(data.eta_days||0),status:'chat'});else{response=makeResponse({order_id:order.id,freelancer_id:user.tg_id,message:msg,proposed_budget:Number(data.proposed_budget||0),eta_days:Number(data.eta_days||0),status:'chat'});state.responses.push(response);}const chat=ensureConversation(order,user.tg_id);addChatMessage(chat,user.tg_id,`Response: ${message}`);pushNotification(order.client_id,{en:`New response on "${localized(order.title)}" from @${user.username}.`,ru:`Новый отклик по заказу "${localized(order.title)}" от @${user.username}.`,uz:`"${localized(order.title)}" buyurtmasiga @${user.username} javob berdi.`});saveState();closeSheet();view.tab='chats';render();openChatSheet(chat.id);toast(t('responseSent'));}
function submitResult(order,resultLink,comment){const user=currentUser();if(state.submissions.some(x=>x.order_id===order.id&&x.freelancer_id===user.tg_id))return toast(t('alreadyResult'));state.submissions.push(makeSubmission({order_id:order.id,freelancer_id:user.tg_id,result_link:resultLink,comment:{en:comment||'',ru:comment||'',uz:comment||''}}));if(!state.responses.some(x=>x.order_id===order.id&&x.freelancer_id===user.tg_id))state.responses.push(makeResponse({order_id:order.id,freelancer_id:user.tg_id,message:{en:comment||'Working result sent.',ru:comment||'Рабочий результат отправлен.',uz:comment||'Ishchi natija yuborildi.'},proposed_budget:order.budget,status:'result'}));const chat=ensureConversation(order,user.tg_id);addChatMessage(chat,user.tg_id,`Working result: ${resultLink}`);updateCurrentUser({balance_freecoins:user.balance_freecoins+50});pushNotification(order.client_id,{en:`New working result on "${localized(order.title)}".`,ru:`Новый рабочий результат по заказу "${localized(order.title)}".`,uz:`"${localized(order.title)}" bo‘yicha yangi natija.`});saveState();closeSheet();view.tab='chats';render();openChatSheet(chat.id);toast(t('resultSent'));}
function contactResponse(id){const r=state.responses.find(x=>x.id===id);if(!r)return;openChatSheet(ensureConversation(orderById(r.order_id),r.freelancer_id).id);}
function contactSubmission(id){const s=state.submissions.find(x=>x.id===id);if(!s)return;openChatSheet(ensureConversation(orderById(s.order_id),s.freelancer_id).id);}
function ensureConversation(order,freelancerId){let chat=state.chats.find(x=>x.order_id===order.id&&x.freelancer_id===freelancerId);if(chat)return chat;chat=makeChat({order_id:order.id,client_id:order.client_id,freelancer_id:freelancerId,messages:[]});state.chats.push(chat);return chat;}
function addChatMessage(chat,senderId,text){const clean=String(text||'').trim();if(!clean)return;chat.messages.push(makeMessage({id:nextId(chat.messages),sender_id:senderId,text:{en:clean,ru:clean,uz:clean}}));}
function openChatSheet(chatId){const chat=state.chats.find(x=>x.id===chatId);if(!chat)return;const user=currentUser();const order=orderById(chat.order_id);const other=user.tg_id===chat.client_id?userById(chat.freelancer_id):userById(chat.client_id);openSheet(`<div class="sheet-head"><h2>${t('chats')}: ${escapeHtml(localized(order?.title)||'Order')}</h2><button class="close-btn" data-close>×</button></div><div class="sheet-body"><div class="chat-peer"><div class="avatar">${initials(other?.username||'FD')}</div><div><strong>@${escapeHtml(other?.username||'user')}</strong><span>${user.tg_id===chat.client_id?t('freelancer'):t('client')}</span></div></div><div class="chat-thread">${chat.messages.map(m=>renderChatMessage(m,user.tg_id)).join('')||`<div class="empty">${t('chatOpen')}</div>`}</div><form class="chat-form" id="chatForm"><textarea class="textarea" name="message" required placeholder="${t('messagePlaceholder')}"></textarea><button class="primary-btn full">${t('send')}</button></form></div>`);document.getElementById('chatForm').addEventListener('submit',e=>{e.preventDefault();const text=String(new FormData(e.currentTarget).get('message')).trim();if(!text)return;addChatMessage(chat,user.tg_id,text);if(other)pushNotification(other.tg_id,{en:`New message on "${localized(order?.title)||'order'}".`,ru:`Новое сообщение по заказу "${localized(order?.title)||'заказ'}".`,uz:`"${localized(order?.title)||'buyurtma'}" bo‘yicha yangi xabar.`});saveState();openChatSheet(chat.id);});}
function renderChatMessage(m,current){const sender=userById(m.sender_id);return `<div class="chat-message ${m.sender_id===current?'mine':''}"><span>@${escapeHtml(sender?.username||'user')}</span><p>${escapeHtml(localized(m.text))}</p></div>`;}function createOrder(data){if(!data.title.en||!data.description.en||!data.budget||data.budget<=0)return toast(t('budget'));const user=currentUser();state.orders.unshift(makeOrder({client_id:user.tg_id,...data}));state.users.filter(u=>u.role==='freelancer').forEach(u=>pushNotification(u.tg_id,{en:`New order: ${data.title.en}.`,ru:`Новый заказ: ${data.title.ru}.`,uz:`Yangi buyurtma: ${data.title.uz}.`}));saveState();closeSheet();toast(t('orderPublishedFree'));render();}function completeOrder(orderId,winningId){const order=orderById(orderId);const winner=state.submissions.find(x=>x.id===winningId);if(!order||!winner||order.status==='completed')return;openCheckout({title:localized(order.title),amount:order.budget,currency:order.currency,note:t('checkoutOrderNote'),submit:t('payNow')},(method)=>settleOrderPayment(orderId,winningId,method));}
function settleOrderPayment(orderId,winningId,method){const order=orderById(orderId);const winner=state.submissions.find(x=>x.id===winningId);if(!order||!winner||order.status==='completed')return;const payout=order.budget*(1-FEE);addBalance(winner.freelancer_id,order.currency,payout);recordPayment({user_id:order.client_id,type:'order_payment',method,currency:order.currency,amount:order.budget,title:localized(order.title),status:'paid'});recordPayment({user_id:winner.freelancer_id,type:'payout',method:'FreeDom',currency:order.currency,amount:payout,title:localized(order.title),status:'paid'});order.status='completed';state.submissions.filter(x=>x.order_id===orderId).forEach(s=>{if(s.id===winningId){s.status='winner';pushNotification(s.freelancer_id,{en:`Order "${localized(order.title)}" was paid.`,ru:`Заказ "${localized(order.title)}" оплачен.`,uz:`"${localized(order.title)}" buyurtmasi to‘landi.`});}else{s.status='rejected';addFreeCoins(s.freelancer_id,100);createMarketItemFromSubmission(order,s);}});saveState();closeSheet();toast(t('winnerPaid'));render();}function createMarketItemFromSubmission(order,s){if(state.marketplace_items.some(x=>x.result_link===s.result_link))return;const min=order.currency==='USD'?10:125000;state.marketplace_items.unshift(makeMarketItem({author_id:s.freelancer_id,title:{en:`Ready solution: ${localized(order.title)}`,ru:`Готовое решение: ${localized(order.title)}`,uz:`Tayyor yechim: ${localized(order.title)}`},description:{en:localized(order.description),ru:localized(order.description),uz:localized(order.description)},result_link:s.result_link,category:order.category,currency:order.currency,price:Math.max(Math.round(order.budget*0.15),min),sales_count:0}));}
function buyMarketplaceItem(id){const item=state.marketplace_items.find(x=>x.id===id);const user=currentUser();if(!item)return;openCheckout({title:localized(item.title),amount:item.price,currency:item.currency,note:t('checkoutMarketNote'),submit:t('payNow')},(method)=>settleMarketplacePurchase(item.id,method));}
function settleMarketplacePurchase(id,method){const item=state.marketplace_items.find(x=>x.id===id);const user=currentUser();if(!item||!user)return;const payout=item.price*(1-FEE);addBalance(item.author_id,item.currency,payout);item.sales_count+=1;recordPayment({user_id:user.tg_id,type:'marketplace_purchase',method,currency:item.currency,amount:item.price,title:localized(item.title),status:'paid'});recordPayment({user_id:item.author_id,type:'marketplace_sale',method:'FreeDom',currency:item.currency,amount:payout,title:localized(item.title),status:'paid'});saveState();closeSheet();toast(t('paymentDone'));render();}
function openCheckout(config,onPaid){openSheet(`<div class="sheet-head"><h2>${t('checkoutTitle')}</h2><button class="close-btn" data-close>×</button></div><div class="sheet-body"><div class="checkout-summary"><span>${escapeHtml(config.title)}</span><strong>${formatMoney(config.amount,config.currency)}</strong><small>${escapeHtml(config.note)}</small></div><form class="form-grid" id="checkoutForm"><div class="field"><label>${t('paymentMethod')}</label><select class="select" name="method"><option>Payme</option><option>Click</option><option>Uzcard / Humo</option><option>Visa / Mastercard</option></select></div><button class="primary-btn full">${config.submit||t('payNow')}</button></form></div>`);document.getElementById('checkoutForm').addEventListener('submit',e=>{e.preventDefault();const method=new FormData(e.currentTarget).get('method');onPaid(method);});}
function recordPayment(item){state.payment_requests.push({id:nextId(state.payment_requests),created_at:new Date().toISOString(),...item});}function openWithdraw(currency){openSheet(`<div class="sheet-head"><h2>${t('withdraw')} ${currency}</h2><button class="close-btn" data-close>×</button></div><div class="sheet-body"><form class="form-grid" id="withdrawForm"><div class="field"><label>${t('destination')}</label><input class="input" name="destination" required></div><div class="field"><label>${t('amount')}</label><input class="input" name="amount" inputmode="decimal" required></div><div class="notice">${t('withdrawNote')}</div><button class="primary-btn full">${t('withdrawRequest')}</button></form></div>`);document.getElementById('withdrawForm').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);const amount=Number(String(f.get('amount')).replace(',','.'));const user=currentUser();const key=currency==='USD'?'balance_usd':'balance_uzs';if(!amount||amount<=0)return;if(user[key]<amount)return toast(t('notEnoughWithdraw'));updateCurrentUser({[key]:user[key]-amount});state.withdraw_requests.push({id:nextId(state.withdraw_requests),user_id:user.tg_id,currency,amount,destination:f.get('destination'),status:'pending_review',created_at:new Date().toISOString()});saveState();closeSheet();toast(t('withdrawDone',{amount:formatMoney(amount,currency)}));render();});}
function logoutUser(){localStorage.removeItem(AUTH_KEY);render();}
function buyPerk(price,title){const user=currentUser();if(user.balance_freecoins<price)return toast(t('notEnoughFC'));updateCurrentUser({balance_freecoins:user.balance_freecoins-price});saveState();toast(t('perkActive',{title}));render();}
function openToolsMenu(){openSheet(`<div class="sheet-head"><h2>${t('toolsMenu')}</h2><button class="close-btn" data-close>×</button></div><div class="sheet-body"><div class="tool-menu-grid"><button class="secondary-btn" data-action="open-ai">${t('ai')}</button><button class="secondary-btn" data-action="open-generator">${t('generator')}</button><button class="secondary-btn" data-action="open-justice">${t('report')}</button><button class="secondary-btn" data-action="open-site">${t('site')}</button></div></div>`);}function openAIAssistant(){openSheet(`<div class="sheet-head"><h2>${t('aiTitle')}</h2><button class="close-btn" data-close>×</button></div><div class="sheet-body"><div class="notice">${t('aiNote')}</div><div class="ai-grid" style="margin-top:12px;"><button class="ghost-btn full" data-ai>${t('aiPlan')}</button><button class="ghost-btn full" data-ai>${t('aiDesc')}</button><button class="ghost-btn full" data-ai>${t('aiCheck')}</button></div><div class="ai-result" id="aiResult">${t('aiReady')}</div></div>`);document.querySelectorAll('[data-ai]').forEach(b=>b.addEventListener('click',()=>document.getElementById('aiResult').textContent=`${b.textContent}: ${t('aiReady')}`));}
function openGenerator(){openSheet(`<div class="sheet-head"><h2>${t('genTitle')}</h2><button class="close-btn" data-close>×</button></div><div class="sheet-body"><form class="form-grid" id="generatorForm"><div class="field"><label>${t('genType')}</label><select class="select" name="type"><option>Website</option><option>Telegram bot</option><option>Landing + request</option></select></div><div class="field"><label>${t('genIdea')}</label><textarea class="textarea" name="idea" required></textarea></div><button class="primary-btn full">${t('genButton')}</button></form><div class="ai-result" id="generatorResult">${t('genResult')}</div></div>`);document.getElementById('generatorForm').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);document.getElementById('generatorResult').textContent=t('genDone',{type:f.get('type'),idea:f.get('idea')});});}
function openJusticeReport(){openSheet(`<div class="sheet-head"><h2>${t('reportTitle')}</h2><button class="close-btn" data-close>×</button></div><div class="sheet-body"><div class="notice">${t('reportNote')}</div><form class="form-grid" id="justiceForm" style="margin-top:12px;"><div class="field"><label>${t('reportTarget')}</label><input class="input" name="target" required></div><div class="field"><label>${t('reportReason')}</label><textarea class="textarea" name="reason" required></textarea></div><button class="danger-btn full">${t('sendReport')}</button></form></div>`);document.getElementById('justiceForm').addEventListener('submit',e=>{e.preventDefault();closeSheet();toast(t('reportDone'));});}
function filteredOrders(){const q=view.orderSearch.trim().toLowerCase();return state.orders.filter(o=>o.status==='open').filter(o=>view.orderCurrency==='all'||o.currency===view.orderCurrency).filter(o=>view.orderCategory==='all'||o.category===view.orderCategory).filter(o=>!q||`${localized(o.title)} ${localized(o.description)}`.toLowerCase().includes(q)).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));}
function filteredMarket(){const q=view.shopSearch.trim().toLowerCase();const min=Number(view.shopMin)||0;const max=Number(view.shopMax)||Infinity;return state.marketplace_items.filter(i=>!q||`${localized(i.title)} ${localized(i.description)} ${categoryLabel(i.category)}`.toLowerCase().includes(q)).filter(i=>i.price>=min&&i.price<=max).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));}
function currentUser(){const session=getSession();const id=session?.tg_id||state.current_tg_id;const user=state.users.find(u=>String(u.tg_id)===String(id));if(user){state.current_tg_id=user.tg_id;return user;}if(session)localStorage.removeItem(AUTH_KEY);state.current_tg_id=state.users[0]?.tg_id;return state.users[0]||null;}
function updateCurrentUser(updates){const user=currentUser();if(!user)return;const i=state.users.findIndex(u=>u.tg_id===user.tg_id);if(i<0)return;state.users[i]={...state.users[i],...updates};state.current_tg_id=state.users[i].tg_id;saveState();}
function userById(id){return state.users.find(u=>u.tg_id===id);}
function orderById(id){return state.orders.find(o=>o.id===id);}
function submissionsFor(orderId){return state.submissions.filter(x=>x.order_id===orderId);}
function responsesFor(orderId){return state.responses.filter(x=>x.order_id===orderId);}
function chatsForUser(tgId){return state.chats.filter(x=>x.client_id===tgId||x.freelancer_id===tgId);}
function lastChatMessage(chat){return chat.messages?.[chat.messages.length-1]||null;}
function addBalance(tgId,currency,amount){const u=userById(tgId);if(!u)return;const key=currency==='USD'?'balance_usd':'balance_uzs';u[key]+=amount;}
function addFreeCoins(tgId,amount){const u=userById(tgId);if(u)u.balance_freecoins+=amount;}
function pushNotification(userId,text){state.notifications.push({id:nextId(state.notifications),user_id:userId,text,created_at:new Date().toISOString()});}
function tabButton(tab,label,icon){return `<button class="${view.tab===tab?'active':''}" data-tab="${tab}"><span>${icon}</span>${label}</button>`;}
function fallbackId(){runtimeIdSeed+=1;return runtimeIdSeed;}function nextId(list){return Math.max(0,...list.map(x=>Number(x.id)||0))+1;}
function formatMoney(value,currency){return currency==='USD'?`$${Number(value).toLocaleString('en-US',{maximumFractionDigits:2})}`:`${Math.round(Number(value)).toLocaleString('ru-RU')} UZS`;}
function formatMainBalance(user){return `${formatMoney(user.balance_usd,'USD')} / ${formatMoney(user.balance_uzs,'UZS')}`;}
function localeCode(){return lang==='ru'?'ru-RU':lang==='uz'?'uz-UZ':'en-US';}function formatNumber(value){return Number(value).toLocaleString(localeCode());}
function statusLabel(status){return {open:'Open',checking:'Checking',completed:'Completed',canceled:'Canceled'}[status]||status;}
function statusClass(status){return status==='completed'?'status-done':status==='canceled'?'status-bad':'status-open';}
function submissionLabel(status){return {pending:t('readyResults'),winner:'Winner',rejected:t('market')}[status]||status;}
function timeLeft(date){const diff=new Date(date)-new Date();if(diff<=0)return '0h';const hours=Math.ceil(diff/36e5);return hours>24?`${Math.ceil(hours/24)}d`:`${hours}h`;}
function stars(rating){return '★'.repeat(Math.round(rating));}
function initials(value){return String(value||'FD').split(/[_\s-]+/).filter(Boolean).slice(0,2).map(p=>p[0]?.toUpperCase()).join('')||'FD';}
function escapeHtml(value){return String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function escapeAttr(value){return escapeHtml(value);}
function iso(value){return new Date(value).toISOString();}
function makeUsername(name){const base=String(name||'user').toLowerCase().replace(/[^a-z0-9а-яё]+/gi,'_').replace(/^_+|_+$/g,'')||'user';let username=base;let n=1;while(state.users.some(u=>u.username===username)){username=`${base}_${n}`;n+=1;}return username;}
function toast(message){const node=document.createElement('div');node.className='toast';node.textContent=message;toastStack.appendChild(node);setTimeout(()=>node.remove(),2600);}
function boot(){
  try {
    render();
  } catch (error) {
    console.error(error);
    app.innerHTML = `<section class="auth-screen"><div class="auth-panel"><div class="brand auth-brand"><div class="brand-mark">FD</div><div><div class="brand-title">FreeDom</div><div class="brand-subtitle">Recovery</div></div></div><h1>FreeDom needs a quick refresh</h1><p>Your saved local session is damaged. We can safely reset only the local demo session and open the platform again.</p></div><div class="auth-form"><button class="primary-btn full" id="repairSession">Repair and continue</button><button class="secondary-btn full" id="openHome">Open home page</button></div></section>`;
    document.getElementById('repairSession')?.addEventListener('click', () => {
      localStorage.removeItem(AUTH_KEY);
      localStorage.removeItem(STORAGE_KEY);
      state = seedState();
      saveState();
      render();
    });
    document.getElementById('openHome')?.addEventListener('click', () => {
      window.location.href = 'index.html';
    });
  }
}

boot();